def _d(title, summary, intro, note, h_model, model_ul, autos, h_sum, sum_table, h_demand, demand_p, demand_table,
       h_end, closing, links):
    """autos: [(title, what, time, money, why)] – 12 разделов."""
    body = [("p", intro), ("note", note), ("h", h_model), ("ul", model_ul)]
    lab = {"time": autos[0][5], "money": autos[0][6], "why": autos[0][7]}
    for i, a in enumerate(autos):
        t, what, tm, mo, why = a[:5]
        body += [("h", f"{i + 1}. {t}"), ("p", what),
                 ("ul", [f"**{lab['time']}:** {tm}", f"**{lab['money']}:** {mo}", f"**{lab['why']}:** {why}"])]
        if i == 1:
            body.append(("code", "restore"))
        if i == 3:
            body.append(("code", "stage"))
    body += [("h", h_sum), ("table", sum_table), ("code", "savings"),
             ("h", h_demand, "contractor-checklist"), ("p", demand_p), ("table", demand_table),
             ("h", h_end), ("p", closing), ("links", links)]
    return {"title": title, "summary": summary, "body": body}


